while (true) {
    ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(500));
    for (ConsumerRecord<String, String> r : records) {
        handle(r);                    // 先处理，失败则抛出不提交位移
    }
    consumer.commitSync();            // 全部处理成功后再提交
}

def retry(fn, *, max_attempts, base=1, is_retryable=lambda e: True, is_done=lambda: False):
    waited = 0
    for attempt in range(1, max_attempts + 1):
        if is_done():
            return "absorbed", waited
        try:
            return fn(), waited
        except Exception as exc:
            if not is_retryable(exc):
                raise
            if attempt == max_attempts:
                raise
            waited += base * (2 ** (attempt - 1))   # 指数退避
    raise RuntimeError("unreachable")

def consume(msgs, *, max_retry=2, fail_kinds=('bad',)):
    processed, dlq, retry = [], [], {}
    i = 0
    while i < len(msgs):
        name, kind = msgs[i]
        if kind not in fail_kinds:
            processed.append(name)
            i += 1
            continue
        retry[name] = retry.get(name, 0) + 1
        if retry[name] > max_retry:
            dlq.append(name)
            i += 1
    first_bad = next((p for p, (_, k) in enumerate(msgs) if k in fail_kinds), len(msgs))
    blocked = sum(1 for _, k in msgs[first_bad:] if k not in fail_kinds)
    return processed, dlq, blocked
